const AdcCaliCoeffs g_cali = {
    .v1 = {0.009759f, 0.045531f},
    .v2 = {0.009756f, 0.025271f},
    .i1 = {0.018785f, -42.239928f},
    .i2 = {0.018632f, -41.895109f},

    // Idel current sense gain: -26.4mV/A * 1.5 = 39.6mV/A
    //   k = 1/4095 * 3000mV / (39.6mV/A) = 0.018500
    //   b = -1500mV / (39.6mV/A) = -37.88
    // => forward transform: i_L = raw * k + b = raw * 0.0185 - 37.88
    // => inverse transform: raw = (i_L + 37.88) / 0.0185 = i_L * 54.054 + 2047.5
    .il_inv = {54.054f, 2047.5f}
};

