// symbol exported by cubemx
extern "C" void SystemClock_Config();

int main()
{
    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_DMA_Init();
    MX_ADC1_Init();
    MX_ADC2_Init();
    MX_COMP1_Init();
    MX_COMP4_Init();
    MX_DAC1_Init();
    MX_DAC3_Init();
    MX_FDCAN2_Init();
    MX_HRTIM1_Init();
    MX_I2C1_Init();
    MX_I2C2_Init();
    MX_USART2_UART_Init();

    g_periphs = {
        .ll_uart = USART2,
        .dac_pcmc = &hdac3,
        .dac_zcd = &hdac1,
        .comp_pcmc = &hcomp1,
        .comp_zcd = &hcomp4,
        .ll_hrtim = HRTIM1,
        .ll_adc1 = ADC1,
        .ll_adc2 = ADC2,
        .i2c_onboard = I2C1,
        .i2c_external = I2C2
    };

    panic::init_panic_resources({
        .uart = g_periphs.ll_uart,
        .led_gpio = LED_G_GPIO_Port,
        .led_gpio_pin = LED_G_Pin,
        .led_active_low = true
    });

    BaseType_t result = xTaskCreate(
        init_and_spawn_task, "init_spawn_task", 512, nullptr,
        PriorityTraits<Priority::kInitAndSpawn>::to_freertos(), nullptr);
    GCHECK(result == pdPASS && "failed to create init and spawn task (out of memory?)");

    vTaskStartScheduler();

    // The scheduler should never return.
    panic::unreachable_code();

    return 0;
}
